//! 🧪️ Named scope and rendering mode follow the shared marker/mode contract.
use super::*;
#[test]
fn portable_marked_content_mode_policy(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧪️fixtures/🔣️.json")).unwrap();for case in fixture["cases"].as_array().unwrap(){let mut scope=MarkedTextScope::default();let mut run=||->Result<bool,String>{if let Some(count)=case["repeatBegin"].as_u64(){for _ in 0..count{scope.begin("Span")?;}}if let Some(ops)=case["ops"].as_array(){for op in ops{if let Some(tag)=op["begin"].as_str(){scope.begin(tag)?;}else{scope.end()?;}}}Ok(case["mode"].as_u64().unwrap()!=3||scope.active())};if let Some(error)=case["error"].as_str(){assert_eq!(run().unwrap_err(),error);}else{assert_eq!(run().unwrap(),case["promote"].as_bool().unwrap());}}for case in fixture["textStrings"].as_array().unwrap(){let bytes=case["bytes"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as u8).collect::<Vec<_>>();assert_eq!(semio_s_artifact_stdio_pdf::standards::v1_7::subsets::base::io::text_string::decode_text_string(&bytes),case["text"].as_str().unwrap());}let mut scope=MarkedTextScope::default();scope.begin(PDF_LAYOUT_TEXT_TAG).unwrap();assert!(scope.finish().is_err());scope.end().unwrap();assert!(scope.finish().is_ok());}

#[test]
fn marked_outline_ownership_requires_supported_successful_promotion(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧪️fixtures/🔣️.json")).unwrap();for row in fixture["paintOwnership"].as_array().unwrap(){let mut owner=MarkedTextScope::default();if let Some(tag)=row["tag"].as_str(){owner.begin(tag).unwrap();}for editable in row["promotions"].as_array().unwrap(){owner.record_promotion(editable.as_bool().unwrap());}assert_eq!(owner.owns_paint(),row["suppress"].as_bool().unwrap());if row["tag"].is_string(){owner.end().unwrap();assert!(!owner.owns_paint());}}for row in fixture["matrices"].as_array().unwrap(){let matrix=std::array::from_fn(|i|row["matrix"][i].as_f64().unwrap());assert_eq!(editable_matrix(matrix,row["scale"].as_f64().unwrap(),row["authored"].as_bool().unwrap()),row["editable"].as_bool().unwrap());}}
